/** Leave an organization. */
const leaveOrg = spacetimedb.reducer({ organizationId: t.string() }, (ctx, { organizationId }) => {
	const member = [...ctx.db.orgMember.byUserId.filter(ctx.sender)].find((m) => m.organizationId === organizationId);
	if (!member) throw new Error("Not a member");
	if (member.role === "owner") throw new Error("Owner cannot leave; transfer ownership first");
	ctx.db.orgMember.delete(member);
});
/**
* Set or clear a member's punch-in code.
* - A user may always set/clear their own code.
* - An owner or a member with `team.edit` permission may set/clear another
*   member's code in the same organization.
* Pass `code: undefined` (option) to clear the code.
*/
const setPunchInCode = spacetimedb.reducer({
	organizationId: t.string(),
	memberId: t.string(),
	code: t.option(t.string())
}, (ctx, { organizationId, memberId, code }) => {
	const caller = findActiveMember(ctx, organizationId);
	const target = [...ctx.db.orgMember.byOrganizationId.filter(organizationId)].find((m) => m.id.toString() === memberId);
	if (!target) throw new Error("Member not found");
	if (!(target.id.toString() === caller.id.toString())) {
		const perms = JSON.parse(caller.permissions);
		if (!(caller.role === "owner" || perms?.team?.edit === true)) unauthorized("Cannot change another member's punch-in code");
	}
	if (code !== void 0) {
		if (!/^[0-9]{4}$/.test(code)) throw new Error("Code must be 4 digits");
		if ([...ctx.db.orgMember.byOrganizationId.filter(organizationId)].find((m) => m.id.toString() !== memberId && m.punchInCode === code)) throw new Error("Code already in use at this store");
	}
	ctx.db.orgMember.delete(target);
	ctx.db.orgMember.insert({
		...target,
		punchInCode: code
	});
});
const recordPunch = spacetimedb.reducer({
	organizationId: t.string(),
	code: t.string(),
	action: t.string()
}, (ctx, { organizationId, code, action }) => {
	findActiveMember(ctx, organizationId);
	const target = [...ctx.db.orgMember.byOrganizationId.filter(organizationId)].find((m) => m.punchInCode === code && m.status === "active");
	if (!target) throw new Error("Invalid punch-in code");
	const memberId = target.id.toString();
	const memberEvents = [...ctx.db.punchEvent.byMemberId.filter(memberId)].filter((e) => e.organizationId === organizationId);
	const openIn = memberEvents.find((e) => e.action === "in" && !e.closed);
	const openBreak = memberEvents.find((e) => e.action === "break-start" && !e.closed);
	const isOnShift = !!openIn;
	const isOnBreak = !!openBreak;
	let resolved = action;
	if (action === "auto") if (!isOnShift) resolved = "in";
	else if (isOnBreak) resolved = "break-end";
	else throw new Error("NEEDS_EXPLICIT_ACTION");
	switch (resolved) {
		case "in":
			if (isOnShift) throw new Error("Already on shift");
			break;
		case "out":
			if (!isOnShift) throw new Error("Not on shift");
			if (isOnBreak) throw new Error("End break before punching out");
			break;
		case "break-start":
			if (!isOnShift) throw new Error("Not on shift");
			if (isOnBreak) throw new Error("Already on break");
			break;
		case "break-end":
			if (!isOnBreak) throw new Error("Not on break");
			break;
		default: throw new Error("Invalid action: " + resolved);
	}
	let pairId = void 0;
	if (resolved === "out" && openIn) {
		pairId = openIn.id.toString();
		ctx.db.punchEvent.delete(openIn);
		ctx.db.punchEvent.insert({
			...openIn,
			closed: true
		});
		if (openBreak) {
			ctx.db.punchEvent.delete(openBreak);
			ctx.db.punchEvent.insert({
				...openBreak,
				closed: true
			});
		}
	}
	if (resolved === "break-end" && openBreak) {
		pairId = openBreak.id.toString();
		ctx.db.punchEvent.delete(openBreak);
		ctx.db.punchEvent.insert({
			...openBreak,
			closed: true
		});
	}
	ctx.db.punchEvent.insert({
		id: ctx.newUuidV4(),
		organizationId,
		memberId,
		pin: code,
		action: resolved,
		at: ctx.timestamp,
		closed: resolved === "out" || resolved === "break-end",
		pairEventId: pairId,
		createdAt: ctx.timestamp
	});
});
const registerDevice = spacetimedb.reducer({
	organizationId: t.string(),
	deviceId: t.string(),
	name: t.string()
}, (ctx, { organizationId, deviceId, name }) => {
	findActiveMember(ctx, organizationId);
	const existing = [...ctx.db.storeDevice.byOrganizationId.filter(organizationId)].find((d) => d.deviceId === deviceId);
	if (existing) {
		ctx.db.storeDevice.delete(existing);
		ctx.db.storeDevice.insert({
			...existing,
			name,
			enabled: true,
			lastSeenAt: ctx.timestamp
		});
	} else ctx.db.storeDevice.insert({
		id: ctx.newUuidV4(),
		organizationId,
		deviceId,
		name,
		enabled: true,
		lastSeenAt: ctx.timestamp,
		registeredBy: ctx.sender,
		createdAt: ctx.timestamp
	});
});
