const addWasteLog = spacetimedb.reducer({
	organizationId: t.string(),
	itemId: t.option(t.string()),
	itemName: t.string(),
	quantity: t.number(),
	unit: t.string(),
	reason: t.string(),
	costPerUnit: t.number(),
	date: t.string(),
	notes: t.option(t.string())
}, (ctx, args) => {
	const member = findActiveMember(ctx, args.organizationId);
	if (!JSON.parse(member.permissions).inventory?.edit) unauthorized("No inventory edit permission");
	const totalCost = args.quantity * args.costPerUnit;
	ctx.db.wasteLog.insert({
		id: ctx.newUuidV4(),
		organizationId: args.organizationId,
		itemId: args.itemId,
		itemName: args.itemName,
		quantity: args.quantity,
		unit: args.unit,
		reason: args.reason,
		costPerUnit: args.costPerUnit,
		totalCost,
		date: args.date,
		notes: args.notes,
		createdBy: member.displayName ?? void 0,
		createdAt: ctx.timestamp
	});
	if (args.itemId) {
		const item = [...ctx.db.inventoryItem.byOrganizationId.filter(args.organizationId)].find((i) => i.id.toString() === args.itemId);
		if (item) {
			const newStock = Math.max(0, item.currentStock - args.quantity);
			const wasAboveMin = item.currentStock > item.minStock;
			ctx.db.inventoryItem.delete(item);
			ctx.db.inventoryItem.insert({
				...item,
				currentStock: newStock,
				updatedAt: ctx.timestamp
			});
			ctx.db.inventoryTransaction.insert({
				id: ctx.newUuidV4(),
				organizationId: args.organizationId,
				itemId: args.itemId,
				itemName: args.itemName,
				type: "loss",
				quantity: args.quantity,
				note: `Waste: ${args.reason}${args.notes ? " — " + args.notes : ""}`,
				date: args.date,
				createdAt: ctx.timestamp
			});
			if (wasAboveMin && newStock <= item.minStock) notifyOrgMembers(ctx, args.organizationId, "inventory_low", `Low stock: ${item.name}`, `${item.name} dropped to ${newStock} ${item.unit} after waste disposal`, "/inventory");
		}
	}
});
